async function fixture(throughSchema?:number){const f=await workFixture({throughSchema});try{
 for(const cap of ['financial-reports.view','payroll-accruals.view','payroll-adjustments.view','session-time.record'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow') ON CONFLICT DO NOTHING",[f.a,cap==='session-time.record'?f.staffRole:f.managerRole,cap]);
 const salary={...f.components[0],earningBasis:'calendar_days'},hourly=f.components.find(c=>c.kind==='hourly')!,project=f.components.find(c=>c.kind==='project')!,e=await f.create({components:[salary,hourly,project]});assert.equal(e.response.status,201);const engagement=e.body.data;
 const expense=await f.made('finance/accounts',{code:'ALL-GROSS',name:'Synthetic gross earning expense',kind:'expense',operationalRole:'expense',hubId:f.hub,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic report mapping'}),liability=await f.made('finance/accounts',{code:'GROSS-DUE',name:'Synthetic gross earning payable',kind:'liability',operationalRole:'payable',hubId:f.hub,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic report mapping'}),base={period:{id:f.period.id,version:1},expenseAccount:{id:expense.id,version:1},liabilityAccount:{id:liability.id,version:1},postedOn:'2026-01-31',dueOn:'2026-02-15',earningReview:'PRIVATE accepted earning',taxReview:'PRIVATE gross base only',reason:'PRIVATE reviewed gross source'};
 const period=await f.made('payroll/pay-periods',{engagementId:engagement.id,workVersion:1,code:'JAN',definition:{from:'2026-01-01',through:'2026-01-31',payOn:'2026-02-15',active:true,timingReview:'PRIVATE explicit service'},reason:'PRIVATE reviewed source'});const {dueOn,...salaryBase}=base;const s=await f.request('payroll/salary-accruals',{...salaryBase,servicePeriod:{id:period.id,version:1},componentCode:'ADMIN',reference:'SALARY'});assert.equal(s.response.status,201,JSON.stringify(s.body));
 const b=await f.request('payroll/adjustments',{...base,engagement:{id:engagement.id,version:1},termsVersion:1,reference:'BONUS',earnedOn:'2026-01-31',amount:'100.25'});assert.equal(b.response.status,201);
 const {earningReview,...projectBase}=base,p=await f.request('payroll/project-accruals',{...projectBase,engagement:{id:engagement.id,version:1},termsVersion:1,componentCode:project.code,deliveryRef:'DELIVERED',units:2,deliveredOn:'2026-01-31',completionReview:'PRIVATE declared project completed'});assert.equal(p.response.status,201,JSON.stringify(p.body));
 const session=(await f.request('classes/'+f.c.id+'/sessions')).body.data[0];assert.equal((await f.request('sessions/'+session.id+'/change',{expectedVersion:1,reason:'Synthetic past delivered class',change:{kind:'reschedule',start:'2026-01-05T10:00',end:'2026-01-05T11:00'}})).response.status,200);const time={expectedVersion:0,assignmentId:f.assignment.id,assignmentVersion:1,sessionVersion:2,startsAt:'2026-01-05T15:00:00Z',endsAt:'2026-01-05T16:00:00Z',reason:'PRIVATE recorded class'};assert.equal((await f.request('sessions/'+session.id+'/my-time',time,'staff')).response.status,201);
 const hourlyInput={...base,personId:f.actors.staff.person,from:'2026-01-05',through:'2026-01-05',timeZone:'UTC',currencyId:f.currency.id,basis:'actual',reference:'HOURS',roundingReview:'PRIVATE actual time retained'},h=await f.request('payroll/hourly-accruals',hourlyInput);assert.equal(h.response.status,201,JSON.stringify(h.body));
 const report=(q='',as='master')=>f.request('reports/payroll/gross-accruals?on=2026-01-31'+q,undefined,as);
 return {...f,engagement,salary,hourly,project,expense,liability,base,projectBase,time,hourlyInput,ids:{salary:s.body.data.id,manual_bonus:b.body.data.id,project:p.body.data.id,hourly:h.body.data.id},report};
 }catch(e){await f.pg.close();throw e;}}
type Fixture=Awaited<ReturnType<typeof fixture>>;
function check(name:string,run:(f:Fixture)=>Promise<void>){test(name,async()=>{const f=await fixture();try{await run(f);}finally{await f.pg.close();}});}
const costs='reports/payroll/costs?from=2026-01-01&through=2026-01-31';
const costParameters={from:'2026-01-01',through:'2026-01-31'};
check('payroll cost CSVs reuse same-source totals and retain private source manifests through the actual job worker',async f=>{
 const direct=await f.request('reports/payroll/costs/export?'+new URLSearchParams(costParameters));assert.equal(direct.response.status,200,JSON.stringify(direct.body));assert.match(direct.response.headers.get('content-disposition')!,/payroll-costs/);const rows=csv(direct.body);assert.equal(rows.find(r=>r.section==='currency_total'&&r.field==='expense')?.amount_minor,'337025');assert.equal(rows.find(r=>r.field==='employerContributionsIncluded')?.value,'true');assert.doesNotMatch(direct.body,/PRIVATE|authorizationContext|sourceId/);
 const key=randomUUID(),queued=await f.request('reports/jobs',{reportId:'payroll.costs',parameters:costParameters},'master',{key});assert.equal(queued.response.status,202,JSON.stringify(queued.body));assert.deepEqual((await f.request('reports/jobs',{reportId:'payroll.costs',parameters:costParameters},'master',{key})).body,queued.body);const work=await background(f);assert.equal(work.outcome,'succeeded',JSON.stringify(work));const id=queued.body.data.id,file=await f.request('reports/jobs/'+id+'/download');assert.equal(file.response.status,200,JSON.stringify(file.body));assert.equal(csv(file.body).find(r=>r.section==='currency_total'&&r.field==='expense')?.amount_minor,'337025');const state=await f.request('reports/jobs/'+id);assert.equal(state.body.result.sha256,createHash('sha256').update(file.body).digest('hex'));assert.equal(state.body.result.bytes,Buffer.byteLength(file.body));assert.equal((await f.request('reports/jobs/'+id+'/download',undefined,'peer')).response.status,404);assert.equal((await f.request('reports/jobs/'+id,undefined,'foreignMaster',{academy:f.b})).response.status,404);
 const proof=(await f.pg.query<{authorization_context:unknown}>('SELECT authorization_context FROM public.report_job_results WHERE job_id=$1',[id])).rows[0].authorization_context;assert.deepEqual(payrollCostAuthorization.parse(proof),{kind:'payroll_cost',sources:Object.entries(f.ids).map(([kind,sourceId])=>({kind,sourceId})).sort((a,b)=>a.kind.localeCompare(b.kind))});assert.doesNotMatch(file.body,/PRIVATE|authorizationContext|sourceId/);
});
check('retained payroll cost files recheck every whole original source without blocking unrelated captured salary files',async f=>{
 for(const cap of ['accounts.view','ledger.view','classes.view'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow') ON CONFLICT DO NOTHING",[f.a,f.managerRole,cap]);const ids=[];for(const parameters of [costParameters,{...costParameters,kind:'salary'}]){const q=await f.request('reports/jobs',{reportId:'payroll.costs',parameters},'manager');assert.equal(q.response.status,202,JSON.stringify(q.body));const r=await background(f);assert.equal(r.outcome,'succeeded',JSON.stringify(r));ids.push(q.body.data.id);}
 await f.pg.query("DELETE FROM public.role_permissions WHERE role_id=$1 AND capability='classes.view'",[f.managerRole]);for(const suffix of ['','/download']){const denied=await f.request('reports/jobs/'+ids[0]+suffix,undefined,'manager');assert.equal(denied.response.status,403,JSON.stringify(denied.body));assert.equal(denied.body.error.code,'REPORT_SOURCE_ACCESS_CHANGED');assert.doesNotMatch(JSON.stringify(denied.body),/sha256|337025/);}assert.equal((await f.request('reports/jobs/'+ids[1]+'/download',undefined,'manager')).response.status,200);assert.equal((await f.request(costs,undefined,'manager')).body.data.currencies[0].expense.amount,'3350.25');
});
check('payroll cost CSV formatter refuses inconsistent partial charts and money while retaining exact source meaning',async f=>{
 const data=(await f.request(costs)).body.data;assert.doesNotThrow(()=>attributionReportCsv(data));assert.throws(()=>attributionReportCsv({...data,charts:{...data.charts,class:[]}}),/ATTRIBUTION_EXPORT_INCOMPLETE/);assert.throws(()=>attributionReportCsv({...data,currencies:[{...data.currencies[0],expense:{minor:'337025',amount:'3370.26'}}]}),/ATTRIBUTION_EXPORT_INCOMPLETE/);
 for(const proof of [{kind:'payroll_cost',sources:[{kind:'salary',sourceId:f.ids.salary},{kind:'salary',sourceId:f.ids.salary}]},{kind:'payroll_cost',sources:[{kind:'other',sourceId:f.ids.salary}]},{kind:'payroll_cost',sources:[{kind:'salary',sourceId:'bad'}]},{kind:'payroll_cost',sources:[],approved:true},{kind:'payroll_cost',sources:[{kind:'salary',sourceId:f.ids.salary,personId:f.actors.staff.person}]}]){assert.equal(payrollCostAuthorization.safeParse(proof).success,false);assert.equal((await f.pg.query<{ok:boolean}>("SELECT public.report_result_context_valid('payroll.costs',$1::jsonb) ok",[JSON.stringify(proof)])).rows[0].ok,false);}
});
check('payroll cost preset CSV and queued relative dates retain one-off provenance without changing saved rules',async f=>{
 const p=await f.request('reports/presets',{anchor:{kind:'hub',id:f.hub},definition:{name:'Reusable payroll cost export',reportId:'payroll.costs',parameters:{},dateWindow:{kind:'previous_month',timeZone:'America/Toronto'}},reason:'Use current source boundaries'});assert.equal(p.response.status,201,JSON.stringify(p.body));const id=p.body.data.id,file=await f.request('reports/presets/'+id+'/export?'+new URLSearchParams(costParameters));assert.equal(file.response.status,200,JSON.stringify(file.body));const metadata=Object.fromEntries(csv(file.body).filter(r=>r.section==='metadata').map(r=>[r.field,r.value]));assert.equal(metadata.presetId,id);assert.deepEqual(JSON.parse(metadata.dateWindow).overriddenFields,['from','through']);
 const queued=await f.request('reports/presets/'+id+'/queue',{expectedVersion:1,overrides:costParameters});assert.equal(queued.response.status,202,JSON.stringify(queued.body));assert.equal((await background(f)).outcome,'succeeded');const saved=await f.request('reports/jobs/'+queued.body.data.id+'/download');assert.equal(saved.response.status,200);assert.equal(csv(saved.body).find(r=>r.section==='currency_total'&&r.field==='expense')?.amount_minor,'337025');assert.deepEqual((await f.request('reports/presets/'+id)).body.data.definition.parameters,{});
});
check('payroll cost queues cancel on current source loss and failed persistence rolls back bytes and generated audit',async f=>{
 for(const cap of ['accounts.view','ledger.view','classes.view'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow') ON CONFLICT DO NOTHING",[f.a,f.managerRole,cap]);const q=await f.request('reports/jobs',{reportId:'payroll.costs',parameters:costParameters},'manager');assert.equal(q.response.status,202);await f.pg.query("DELETE FROM public.role_permissions WHERE role_id=$1 AND capability IN('payroll-accruals.view','payroll-adjustments.view')",[f.managerRole]);assert.equal((await background(f)).outcome,'cancelled');assert.equal((await f.pg.query('SELECT * FROM public.report_job_results')).rows.length,0);
 const next=await f.request('reports/jobs',{reportId:'payroll.costs',parameters:costParameters});assert.equal(next.response.status,202);await f.pg.exec('CREATE FUNCTION public.suppress_cost_result_test() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RETURN NULL;END$$;CREATE TRIGGER suppress_cost_result_test BEFORE INSERT ON public.report_job_results FOR EACH ROW EXECUTE FUNCTION public.suppress_cost_result_test()');try{assert.equal((await background(f)).outcome,'retry');}finally{await f.pg.exec('DROP TRIGGER suppress_cost_result_test ON public.report_job_results;DROP FUNCTION public.suppress_cost_result_test()');}assert.equal((await f.pg.query('SELECT * FROM public.report_job_results')).rows.length,0);assert.equal((await f.pg.query("SELECT * FROM public.audit_events WHERE action='report.generated'")).rows.length,0);
 await f.pg.exec('BEGIN;SET LOCAL ROLE kavosh_automation_policy');try{await f.pg.query("UPDATE public.report_jobs SET available_at=clock_timestamp()-interval '1 second' WHERE id=$1",[next.body.data.id]);await f.pg.exec('COMMIT');}catch(e){await f.pg.exec('ROLLBACK');throw e;}assert.equal((await background(f)).outcome,'succeeded');assert.equal((await f.pg.query('SELECT * FROM public.report_job_results')).rows.length,1);
});
if(process.env.TEST_DATABASE_URL&&process.env.RUN_REAL_CLOCK_PAYROLL_COST_CHECK==='true')test('real-clock payroll cost schedule runs the restricted packaged daemon without an API tick',{timeout:90000},async()=>{
 const f=await fixture();let child:ReturnType<typeof spawn>|undefined,login:string|undefined;try{
  for(const cap of ['accounts.view','ledger.view','classes.view','report-presets.view','report-schedules.view','report-schedules.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow') ON CONFLICT DO NOTHING",[f.a,f.managerRole,cap]);const due=(await f.pg.query<{due:string}>("SELECT to_char((date_trunc('minute',clock_timestamp())+(CASE WHEN extract(second FROM clock_timestamp())>=55 THEN interval '2 minutes' ELSE interval '1 minute' END)) AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"') due")).rows[0].due;
  const preset=await f.request('reports/presets',{anchor:{kind:'hub',id:f.hub},definition:{name:'Scheduled payroll cost CSV',reportId:'payroll.costs',parameters:{},dateWindow:{kind:'last_days',days:3660,timeZone:'UTC'}},reason:'Actual isolated clock test'});assert.equal(preset.response.status,201);const schedule=await f.request('reports/presets/'+preset.body.data.id+'/schedules',{definition:{name:'Reviewed cost schedule',presetVersion:1,timing:{timeZone:'UTC',localTime:due.slice(11,16),startsOn:due.slice(0,10),cycle:{kind:'daily'},maxDelayMinutes:60}},reason:'Actual wall-clock schedule'},'manager');assert.equal(schedule.response.status,202,JSON.stringify(schedule.body));const approved=await f.approve(schedule.body.approval.id);assert.equal(approved.response.status,200,JSON.stringify(approved.body));assert.equal(Date.parse(approved.body.data.nextPlannedOccurrence),Date.parse(due));
  const name=(await f.pg.query<{name:string}>('SELECT current_database() name')).rows[0].name;assert.match(name,/^kavosh_test_[a-f0-9]{32}$/);login='kavosh_cost_'+randomUUID().replaceAll('-','');const password='synthetic_only_'+randomUUID().replaceAll('-','');await f.pg.exec(`CREATE ROLE ${login} LOGIN NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS PASSWORD '${password}';GRANT kavosh_automation_worker TO ${login}`);const url=new URL(process.env.TEST_DATABASE_URL!);url.username=login;url.password=password;url.pathname='/'+name;let output='';const command=process.env.REPORT_WORKER_COMPILED_ENTRY?[process.env.REPORT_WORKER_COMPILED_ENTRY]:['--import','tsx','scripts/process-reports.ts'];child=spawn(process.execPath,command,{cwd:process.cwd(),env:{PATH:process.env.PATH,NODE_ENV:'test',DATABASE_SSL_MODE:'disable',REPORT_WORKER_ENABLED:'true',REPORT_SCHEDULER_ENABLED:'true',REPORT_WORKER_DATABASE_URL:url.toString(),REPORT_WORKER_ACADEMIES:JSON.stringify([f.a])},stdio:['ignore','ignore','pipe']});child.stderr?.on('data',b=>{if(output.length<2000)output+=String(b).slice(0,2000-output.length);});
  const began=performance.now(),deadline=began+75000;let finished=false;while(performance.now()<deadline){finished=(await f.pg.query("SELECT 1 FROM public.report_jobs WHERE status='succeeded'")).rows.length===1;if(finished||child.exitCode!==null)break;await delay(500);}assert.ok(finished,'Scheduled payroll cost generation did not finish: '+output);const jobs=(await f.pg.query<{id:string;requester_id:string;window_resolution:{resolvedAt:string}}>('SELECT id,requester_id,window_resolution FROM public.report_jobs')).rows;assert.equal(jobs.length,1);assert.equal(jobs[0].requester_id,f.actors.manager.person);assert.equal(Date.parse(jobs[0].window_resolution.resolvedAt),Date.parse(due));const file=await f.request('reports/jobs/'+jobs[0].id+'/download',undefined,'manager');assert.equal(file.response.status,200,JSON.stringify(file.body));const rows=csv(file.body);assert.equal(rows.find(r=>r.section==='currency_total'&&r.field==='expense')?.amount_minor,'337025');assert.equal(Date.parse(JSON.parse(rows.find(r=>r.field==='scheduledOccurrence')!.value).dueAt),Date.parse(due));const exited=new Promise<number|null>(resolve=>child!.once('exit',resolve));child.kill('SIGTERM');assert.equal(await Promise.race([exited,delay(2000,undefined,{ref:false}).then(()=>-1)]),0);assert.doesNotMatch(output,/postgresql:|synthetic_only_|password|token_hash/i);console.log(JSON.stringify({measurement:'real-clock-payroll-cost',jobs:1,elapsedMs:Math.ceil(performance.now()-began),providerIO:false}));
 }finally{if(child&&child.exitCode===null){child.kill('SIGKILL');await new Promise(resolve=>child!.once('exit',resolve));}if(login)await f.pg.exec('DROP ROLE '+login);await f.pg.close();}
});
test('payroll cost capture uses one real money and source snapshot while another bonus commits',{skip:!process.env.TEST_DATABASE_URL},async()=>{
 const f=await fixture();try{const queued=await f.request('reports/jobs',{reportId:'payroll.costs',parameters:costParameters});assert.equal(queued.response.status,202);let sourceQueries=0,bonusId:string|undefined;const database:Database={async connect(){const c=await f.pg.runtime!.connect();await c.query('SET ROLE kavosh_automation_worker');return {async query<Row>(sql:string,params?:unknown[]){const r=await c.query<Row>(sql,params);if(sql.startsWith('WITH sources AS')&&sql.includes('"authorizationContext"')){sourceQueries++;const bonus=await f.request('payroll/adjustments',{...f.base,engagement:{id:f.engagement.id,version:1},termsVersion:1,reference:'COST-SNAPSHOT-BONUS',earnedOn:'2026-01-31',amount:'1.00'});assert.equal(bonus.response.status,201,JSON.stringify(bonus.body));bonusId=bonus.body.data.id;}return r;},release(destroy?:boolean){c.release(destroy);}};}};
 const began=performance.now(),worked=await processOneReport(database,[f.a]);assert.equal(worked.outcome,'succeeded');assert.equal(sourceQueries,1);assert.ok(bonusId);const file=await f.request('reports/jobs/'+queued.body.data.id+'/download');assert.equal(file.response.status,200);assert.equal(csv(file.body).find(r=>r.section==='currency_total'&&r.field==='expense')?.amount_minor,'337025');const proof=(await f.pg.query('SELECT authorization_context FROM public.report_job_results WHERE job_id=$1',[queued.body.data.id])).rows[0].authorization_context;assert.equal(JSON.stringify(proof).includes(bonusId),false);assert.equal((await f.request(costs)).body.data.currencies[0].expense.minor,'337125');console.log(JSON.stringify({measurement:'brief-payroll-cost-snapshot',elapsedMs:Math.ceil(performance.now()-began),requests:2,productionSlo:false}));
 }finally{await f.pg.close();}
});
