check('payroll relative-window export preserves explicit date override provenance and supports a reviewed payroll schedule',async f=>{
 const saved=await f.request('reports/presets',{anchor:{kind:'hub',id:f.hub},definition:{name:'Current payroll',reportId:'payroll.gross-accruals',parameters:{},dateWindow:{kind:'today',timeZone:'America/Toronto'}},reason:'Current civil reporting day'});assert.equal(saved.response.status,201,JSON.stringify(saved.body));const id=saved.body.data.id,file=await f.request('reports/presets/'+id+'/export?on=2026-01-31');assert.equal(file.response.status,200,JSON.stringify(file.body));const meta=Object.fromEntries(csv(file.body).filter(v=>v.section==='metadata').map(v=>[v.field,v.value]));assert.equal(meta.on,'2026-01-31');assert.equal(meta.dateWindowKind,'today');assert.equal(meta.dateWindowTimeZone,'America/Toronto');assert.deepEqual(JSON.parse(meta.dateWindowOverriddenFields),['on']);assert.ok(Number.isFinite(Date.parse(meta.dateWindowResolvedAt)));assert.equal(csv(file.body).filter(v=>v.section==='earning').length,4);
 const scheduled=await f.request('reports/presets/'+id+'/schedules',{definition:{name:'Reviewed payroll schedule',enabled:true,presetVersion:1,timing:{timeZone:'America/Toronto',localTime:'03:00',startsOn:'2026-01-01',cycle:{kind:'monthly',day:1}}},reason:'Do not bypass the payroll result-access model'});assert.equal(scheduled.response.status,201,JSON.stringify(scheduled.body));assert.equal((await f.pg.query('SELECT * FROM public.report_schedules')).rows.length,1);
});
