test('gross report source and chart budgets refuse truncation without running a large stress suite',()=>{assertPayrollGrossBounds({allocations:10000,currencyGroups:1000,chartGroups:1000});for(const values of [{allocations:10001,currencyGroups:0,chartGroups:0},{allocations:1,currencyGroups:1001,chartGroups:0},{allocations:1,currencyGroups:1,chartGroups:1001}])assert.throws(()=>assertPayrollGrossBounds(values),/GROSS_EARNINGS_REPORT_REQUIRES_BACKGROUND_JOB/);});
check('report rejects invalid dates, duplicate parameters, unsupported methods and incomplete cursors',async f=>{
 for(const q of ['on=2026-02-30','on=2026-01-31&limit=0','on=2026-01-31&kind=other','on=2026-01-31&limit=1&limit=2','on=2026-01-31&afterKind=salary','on=2026-01-31&unknown=true'])assert.equal((await f.request('reports/payroll/gross-accruals?'+q)).response.status,400,q);assert.equal((await f.request('reports/payroll/gross-accruals?on=2026-01-31',{})).response.status,405);
});
